    clauses = [list(c) for c in inst["clauses"]]
    assign = {}

    def propagate():
        changed = True
        while changed:
            changed = False
            for c in clauses:
                sat = False
                unassigned = []
                for l in c:
                    v = abs(l)
                    if v in assign:
                        if assign[v] == (l > 0):
                            sat = True
                            break
                    else:
                        unassigned.append(l)
                if sat:
                    continue
                if not unassigned:
                    return False
                if len(unassigned) == 1:
                    l = unassigned[0]
                    v = abs(l)
                    val = l > 0
                    if v in assign and assign[v] != val:
                        return False
                    if v not in assign:
                        assign[v] = val
                        changed = True
        return True

    def rec():
        saved = dict(assign)
        if not propagate():
            assign.clear(); assign.update(saved)
            return False
        # all clauses satisfied?
        for c in clauses:
            if not any(abs(l) in assign and assign[abs(l)] == (l > 0) for l in c):
                break
        else:
            return True
        # branch on an unassigned var appearing in an unsatisfied clause
        var = None
        for c in clauses:
