                for l in c:
                    if abs(l) not in assign:
                        var = abs(l)
                        break
                if var is not None:
                    break
        if var is None:
            return True
        for val in (True, False):
            assign[var] = val
            if rec():
                return True
            assign.pop(var, None)
        assign.clear(); assign.update(saved)
        return False

